from pathlib import Path
import os,subprocess
projects={
 'fadego':('/etc/systemd/system/fadego-staging.service','/srv/fadego-staging','/srv/projects/fadego'),
 'lowcost-europa':('/etc/systemd/system/lowcost-europa.service','/srv/lowcost-europa','/srv/projects/lowcost-europa'),
 'pink-iptv':('/etc/systemd/system/pink-iptv-backend.service','/srv/pink-iptv','/srv/projects/pink-iptv')
}
for name,(file,old,new) in projects.items():
 p=Path(file)
 print('===UNIT==='+name)
 print('EXISTS',p.is_file(),'SYMLINK',p.is_symlink(),'OWNER',p.stat().st_uid if p.exists() else '?')
 if not p.is_file() or p.is_symlink():continue
 raw=p.read_text(errors='replace')
 print('OLD_REF_COUNT',raw.count(old),'NEW_REF_COUNT',raw.count(new))
 for i,line in enumerate(raw.splitlines(),1):
  st=line.strip()
  if st.startswith('WorkingDirectory='):
   print('WORKING_DIRECTORY',i,st)
  elif st.startswith('ExecStart='):
   print('START_PATH_REFERENCES',i,'old',line.count(old),'new',line.count(new),'head',st.split()[0][:160])
  elif st.startswith('EnvironmentFile='):
   print('ENVIRONMENT_FILE',i,'REFERENCES_EXTERNAL',old in st)
  elif st.startswith(('User=','Group=','Restart=','StateDirectory=','CacheDirectory=','LogsDirectory=')):
   print('UNIT_META',i,st[:200])
 for sub in ['/etc/systemd/system/'+Path(file).name+'.d']:
  s=Path(sub)
  print('DROPIN_DIR',sub,s.is_dir())
 if name=='lowcost-europa':
  for q in ['.venv/bin/python','.venv/bin/gunicorn','manage.py']:
   f=Path(new)/q
   print('EXE',q,'EXISTS',f.exists(),'SYM',f.is_symlink())
   if f.is_file() and q.endswith('gunicorn'):
    with f.open('rb') as g:print('SHEBANG',g.readline().decode(errors='replace').strip()[:160])
 if name=='pink-iptv':
  f=Path(new)/'backend/.venv/bin/uvicorn'
  print('UVICORN',f.exists())
  if f.is_file():
   with f.open('rb') as g:print('SHEBANG',g.readline().decode(errors='replace').strip()[:160])
print('===SERVICE_REFS_IN_NGINX===')
base=Path('/etc/nginx')
for f in base.rglob('*'):
 if not f.is_file() or f.is_symlink() or f.stat().st_size>180000:continue
 try:
  txt=f.read_text(errors='replace')
  matches=[m for m in ('/srv/fadego-staging','/srv/lowcost-europa','/srv/pink-iptv') if m in txt]
  if matches:print('NGINX_REF',str(f),','.join(matches))
 except OSError:pass
print('===ROOT PATHS===')
for _,(_,old,new) in projects.items():
 print('PATH',old,'SYMLINK',Path(old).is_symlink(),'TARGET_IS_DIR',Path(new).is_dir())
print('UNIT_PREFLIGHT=PASS')
